from jsonb_to_recordset($q$[{"id":6139,"materia":"ling","nivel":0,"enunciado":"Em “O sino da igreja fazia blém, blém, blém”, a figura de linguagem é a:","opcoes":["Onomatopeia","Metáfora","Ironia","Hipérbole"],"explicacao":"A onomatopeia imita sons."},{"id":6140,"materia":"ling","nivel":2,"enunciado":"Na fala de uma comunidade rural, aparece “nóis vai”. Do ponto de vista da linguística, isso é:","opcoes":["Uma variação linguística legítima, própria daquele grupo","Um erro sem nenhuma regra, que deve ser corrigido sempre","Uma língua estrangeira","Um caso de metáfora"],"explicacao":"A variedade segue regras próprias; o preconceito linguístico ignora isso."},{"id":6141,"materia":"ling","nivel":2,"enunciado":"Em “Memórias Póstumas de Brás Cubas”, de Machado de Assis, o narrador é:","opcoes":["Um defunto que conta a própria vida","Um padre","Uma criança","Um narrador que não participa da história"],"explicacao":"O “defunto autor” inaugura o Realismo no Brasil."},{"id":6142,"materia":"ling","nivel":3,"enunciado":"“Iracema”, de José de Alencar, é um romance:","opcoes":["Indianista do Romantismo","Realista","Modernista","Parnasiano"],"explicacao":"Iracema é anagrama de América."},{"id":6143,"materia":"ling","nivel":3,"enunciado":"A poesia da “arte pela arte”, com rigor formal e rimas raras, de autores como Olavo Bilac, pertence ao:","opcoes":["Parnasianismo","Romantismo","Modernismo","Arcadismo"],"explicacao":"Fim do século XIX."},{"id":6144,"materia":"ling","nivel":3,"enunciado":"Num texto em inglês, a palavra “however” indica:","opcoes":["Oposição (no entanto)","Adição (além disso)","Conclusão (portanto)","Tempo (depois)"],"explicacao":"However = contudo, no entanto."},{"id":6145,"materia":"ling","nivel":3,"enunciado":"Em espanhol, “exquisito” significa:","opcoes":["Delicioso","Esquisito","Estranho","Feio"],"explicacao":"É um falso cognato."},{"id":6146,"materia":"ling","nivel":3,"enunciado":"As antíteses, o conflito entre fé e pecado e a poesia satírica de Gregório de Matos marcam o:","opcoes":["Barroco","Arcadismo","Simbolismo","Realismo"],"explicacao":"Século XVII, na Bahia."},{"id":6147,"materia":"ling","nivel":4,"enunciado":"Em “O aluno chegou cedo. Ele queria estudar”, o pronome “Ele” retoma “O aluno”. Esse recurso de coesão é a:","opcoes":["Anáfora","Catáfora","Elipse","Antítese"],"explicacao":"A catáfora antecipa um termo que vem depois."},{"id":6148,"materia":"mat","nivel":1,"enunciado":"Um terreno retangular mede 12 m por 20 m. Sua área é:","opcoes":["240 m²","64 m²","32 m²","2.400 m²"],"explicacao":"Área = 12 × 20."},{"id":6149,"materia":"mat","nivel":2,"enunciado":"Num mapa com escala 1:100.000, 5 cm correspondem, na realidade, a:","opcoes":["5 km","500 m","50 km","5 m"],"explicacao":"5 cm × 100.000 = 500.000 cm = 5 km."},{"id":6150,"materia":"mat","nivel":2,"enunciado":"Os salários de cinco funcionários são R$ 1 mil, 2 mil, 3 mil, 10 mil e 50 mil. A medida que melhor representa o salário típico, sem distorção pelo valor alto, é a:","opcoes":["Mediana, de R$ 3 mil","Média, de R$ 13,2 mil","Moda","Amplitude, de R$ 49 mil"],"explicacao":"A média é puxada pelo valor extremo."},{"id":6151,"materia":"mat","nivel":3,"enunciado":"Uma caixa d’água em forma de cubo tem 2 m de aresta. Ela comporta:","opcoes":["8.000 litros","800 litros","6.000 litros","4.000 litros"],"explicacao":"Volume = 2³ = 8 m³; 1 m³ = 1.000 L."},{"id":6152,"materia":"mat","nivel":3,"enunciado":"Na progressão aritmética 3, 7, 11, 15, ..., o 20º termo é:","opcoes":["79","80","83","75"],"explicacao":"a20 = 3 + 19 × 4 = 79."},{"id":6153,"materia":"mat","nivel":3,"enunciado":"Quanto vale log₂ 32?","opcoes":["5","16","6","4"],"explicacao":"2⁵ = 32."},{"id":6154,"materia":"mat","nivel":3,"enunciado":"Uma rampa de 10 m de comprimento forma 30° com o chão. A altura que ela vence é:","opcoes":["5 m","10 m","8,66 m","3 m"],"explicacao":"Altura = 10 × sen 30° = 10 × 0,5."},{"id":6155,"materia":"mat","nivel":2,"enunciado":"Quantos anagramas tem a palavra AMOR?","opcoes":["24","12","4","16"],"explicacao":"4! = 24."},{"id":6156,"materia":"mat","nivel":4,"enunciado":"O vértice da parábola y = x² − 4x + 3 tem abscissa:","opcoes":["x = 2","x = −2","x = 4","x = 3"],"explicacao":"xv = −b/2a = 4/2 = 2."},{"id":6157,"materia":"mat","nivel":4,"enunciado":"Numa turma, 60% são mulheres. Usam óculos 50% das mulheres e 25% dos homens. Escolhida ao acaso uma pessoa de óculos, a chance de ser mulher é:","opcoes":["75%","50%","60%","30%"],"explicacao":"Mulheres de óculos: 30%; homens: 10%. 30 ÷ 40 = 75%."},{"id":6158,"materia":"mat","nivel":1,"enunciado":"Um produto de R$ 250,00 teve aumento de 20%. O novo preço é:","opcoes":["R$ 300,00","R$ 270,00","R$ 350,00","R$ 280,00"],"explicacao":"20% de 250 = 50."},{"id":6159,"materia":"fis","nivel":1,"enunciado":"Um carro a 72 km/h está a quantos metros por segundo?","opcoes":["20 m/s","72 m/s","7,2 m/s","259 m/s"],"explicacao":"Divide-se por 3,6."},{"id":6160,"materia":"fis","nivel":2,"enunciado":"Um resistor de 4 Ω é ligado a uma tensão de 12 V. A corrente que passa por ele é:","opcoes":["3 A","48 A","8 A","16 A"],"explicacao":"i = U ÷ R."},{"id":6161,"materia":"fis","nivel":1,"enunciado":"No eclipse lunar, quem fica entre o Sol e a Lua é:","opcoes":["A Terra","Marte","Vênus","Ninguém"],"explicacao":"A sombra da Terra cobre a Lua."},{"id":6162,"materia":"fis","nivel":1,"enunciado":"No espaço, onde há vácuo, uma explosão:","opcoes":["Não seria ouvida, pois o som precisa de um meio","Seria ouvida mais alto, pois não há ar para abafar o som","Seria ouvida igual","Seria ouvida só de dia"],"explicacao":"O som é onda mecânica."},{"id":6163,"materia":"fis","nivel":2,"enunciado":"Um canudo dentro de um copo d’água parece “quebrado”. Isso acontece por causa da:","opcoes":["Refração da luz","Reflexão total","Difração do som","Interferência magnética"],"explicacao":"A luz muda de velocidade ao passar da água para o ar."},{"id":6164,"materia":"fis","nivel":3,"enunciado":"Enquanto o gelo derrete, a 0 °C, a temperatura da mistura de água e gelo:","opcoes":["Fica constante","Aumenta sem parar","Diminui","Oscila"],"explicacao":"A energia vai para a mudança de estado (calor latente)."},{"id":6165,"materia":"fis","nivel":2,"enunciado":"Nas casas, as lâmpadas são ligadas em paralelo. Por isso, se uma queima:","opcoes":["As outras continuam acesas","Todas apagam","As outras brilham mais","A casa toda fica sem energia até trocar a lâmpada"],"explicacao":"Cada uma tem seu próprio caminho de corrente."},{"id":6166,"materia":"fis","nivel":4,"enunciado":"O período de oscilação de um pêndulo simples depende:","opcoes":["Do comprimento do fio e da gravidade","Da massa do corpo","Da cor do corpo","Só da amplitude da oscilação, mesmo quando ela é grande"],"explicacao":"T = 2π√(L/g), para pequenas oscilações."},{"id":6167,"materia":"fis","nivel":3,"enunciado":"Um navio de aço flutua porque:","opcoes":["Desloca um volume de água cujo peso é igual ao seu","O aço usado em navios é mais leve que a água do mar","A água do mar não tem peso","O navio não tem massa"],"explicacao":"Princípio de Arquimedes (empuxo)."},{"id":6168,"materia":"qui","nivel":2,"enunciado":"Para obter água pura a partir da água do mar, usa-se a:","opcoes":["Destilação","Filtração","Decantação","Peneiração"],"explicacao":"O sal fica, e a água evaporada é condensada."},{"id":6169,"materia":"qui","nivel":3,"enunciado":"Balanceando a equação H₂ + O₂ → H₂O, os menores coeficientes inteiros são:","opcoes":["2, 1 e 2","1, 1 e 1","1, 2 e 2","2, 2 e 1"],"explicacao":"2 H₂ + O₂ → 2 H₂O."},{"id":6170,"materia":"qui","nivel":2,"enunciado":"Sabendo que C = 12 e O = 16, a massa molar do CO₂ é:","opcoes":["44 g/mol","28 g/mol","32 g/mol","40 g/mol"],"explicacao":"12 + 2 × 16."},{"id":6171,"materia":"qui","nivel":3,"enunciado":"Dissolvem-se 20 g de açúcar em água até completar 500 mL. A concentração é:","opcoes":["40 g/L","10 g/L","4 g/L","100 g/L"],"explicacao":"20 g ÷ 0,5 L."},{"id":6172,"materia":"qui","nivel":2,"enunciado":"A queima do gás de cozinha é uma reação:","opcoes":["Exotérmica, que libera calor","Endotérmica, que absorve calor","Nuclear","Sem troca de energia"],"explicacao":"Toda combustão libera energia."},{"id":6173,"materia":"qui","nivel":4,"enunciado":"Uma amostra radioativa de 100 g tem meia-vida de 5 anos. Após 15 anos, restam:","opcoes":["12,5 g","25 g","50 g","33 g"],"explicacao":"100 → 50 → 25 → 12,5."},{"id":6174,"materia":"qui","nivel":2,"enunciado":"O etanol, usado como combustível, pertence à função orgânica:","opcoes":["Álcool","Ácido carboxílico","Éter","Aldeído"],"explicacao":"Tem o grupo –OH ligado a carbono saturado."},{"id":6175,"materia":"qui","nivel":4,"enunciado":"Um catalisador, numa reação química:","opcoes":["Aumenta a velocidade sem ser consumido","É consumido e vira um dos produtos da reação","Muda os produtos formados","Diminui sempre a velocidade"],"explicacao":"Diminui a energia de ativação."},{"id":6176,"materia":"bio","nivel":1,"enunciado":"As vacinas protegem porque:","opcoes":["Estimulam o corpo a produzir anticorpos e células de memória","Matam todos os vírus e bactérias do corpo assim que aplicadas","Substituem o sangue","Funcionam como antibióticos"],"explicacao":"É a imunização ativa."},{"id":6177,"materia":"bio","nivel":1,"enunciado":"Os antibióticos NÃO funcionam contra:","opcoes":["Vírus","Bactérias","Infecções bacterianas","Bactérias resistentes, às vezes"],"explicacao":"Gripe e resfriado são causados por vírus."},{"id":6178,"materia":"bio","nivel":3,"enunciado":"A divisão celular que forma os gametas, com metade dos cromossomos, é a:","opcoes":["Meiose","Mitose","Fissão binária","Brotamento"],"explicacao":"A mitose gera células iguais à original."},{"id":6179,"materia":"bio","nivel":4,"enunciado":"O excesso de nutrientes, como fósforo e nitrogênio de esgoto, num lago provoca:","opcoes":["Eutrofização, com proliferação de algas e queda de oxigênio","Aumento da biodiversidade de peixes e da oxigenação da água","Água mais limpa","Congelamento do lago