{"id":6187,"materia":"geo","nivel":2,"enunciado":"Em relação ao horário de Greenwich, o horário oficial de Brasília é:","opcoes":["3 horas a menos","3 horas a mais","Igual","5 horas a menos"],"explicacao":"UTC−3."},{"id":6188,"materia":"geo","nivel":2,"enunciado":"O centro das grandes cidades costuma ser mais quente que a periferia. Esse fenômeno é a:","opcoes":["Ilha de calor","Inversão térmica","Chuva ácida","Maré"],"explicacao":"Causado por asfalto, concreto e pouca vegetação."},{"id":6189,"materia":"geo","nivel":2,"enunciado":"O principal comprador da soja brasileira é a:","opcoes":["China","Argentina","Rússia","Índia"],"explicacao":"Mais da metade das exportações vai para lá."},{"id":6190,"materia":"geo","nivel":2,"enunciado":"Com a queda da natalidade e o aumento da expectativa de vida, a pirâmide etária brasileira:","opcoes":["Estreita na base e alarga no topo","Fica mais larga na base, com mais crianças","Não muda","Vira um triângulo perfeito"],"explicacao":"É o envelhecimento da população."},{"id":6191,"materia":"geo","nivel":4,"enunciado":"A valorização de um bairro popular que expulsa os moradores antigos, que não conseguem pagar os novos preços, chama-se:","opcoes":["Gentrificação","Conurbação","Metropolização","Êxodo rural"],"explicacao":"Comum em centros revitalizados."},{"id":6192,"materia":"geo","nivel":4,"enunciado":"A degradação do solo em regiões semiáridas, por desmatamento e uso inadequado, chama-se:","opcoes":["Desertificação","Laterização","Lixiviação","Assoreamento"],"explicacao":"Atinge áreas do Nordeste."},{"id":6193,"materia":"geo","nivel":2,"enunciado":"O clima quente e úmido o ano todo, com muitas chuvas, típico da Amazônia, é o:","opcoes":["Equatorial","Semiárido","Subtropical","Tropical de altitude"],"explicacao":"Pouca variação de temperatura."},{"id":6194,"materia":"fil","nivel":3,"enunciado":"Para Marx, o lucro do capitalista vem da:","opcoes":["Mais-valia, o trabalho não pago ao operário","Sorte nos negócios e da habilidade de negociar","Caridade","Natureza"],"explicacao":"A história é a história da luta de classes."},{"id":6195,"materia":"fil","nivel":3,"enunciado":"Para Durkheim, as maneiras de agir, pensar e sentir exteriores ao indivíduo e que se impõem a ele são os:","opcoes":["Fatos sociais","Tipos ideais","Modos de produção","Instintos"],"explicacao":"Ex.: a língua, as leis, a moral."},{"id":6196,"materia":"fil","nivel":4,"enunciado":"A frase “Deus está morto” e o conceito de “super-homem” (além-do-homem) são de:","opcoes":["Nietzsche","Kant","Santo Tomás de Aquino","Platão"],"explicacao":"Crítica aos valores tradicionais."},{"id":6197,"materia":"fil","nivel":4,"enunciado":"A frase “a existência precede a essência” resume o existencialismo de:","opcoes":["Jean-Paul Sartre","Aristóteles","Hegel","Locke"],"explicacao":"O ser humano se define por suas escolhas."},{"id":6198,"materia":"fil","nivel":2,"enunciado":"A passagem de uma pessoa de uma classe social para outra chama-se:","opcoes":["Mobilidade social","Estratificação fixa","Anomia","Alienação"],"explicacao":"Pode ser ascendente ou descendente."},{"id":6199,"materia":"ling","nivel":3,"enunciado":"A resenha crítica combina:","opcoes":["Resumo da obra e avaliação do autor da resenha","Apenas a lista de personagens e o resumo do enredo","Só a biografia do autor","Uma receita e uma propaganda"],"explicacao":"Informa e opina sobre um livro, filme etc."},{"id":6200,"materia":"ling","nivel":3,"enunciado":"“Grande Sertão: Veredas”, com muitos neologismos e o narrador Riobaldo, é de:","opcoes":["Guimarães Rosa","Jorge Amado","Graciliano Ramos","Érico Veríssimo"],"explicacao":"Publicado em 1956."},{"id":6201,"materia":"ling","nivel":2,"enunciado":"O poema que repete “No meio do caminho tinha uma pedra” é de:","opcoes":["Carlos Drummond de Andrade","Manuel Bandeira","Mário Quintana","Olavo Bilac"],"explicacao":"Publicado em 1928, causou polêmica."},{"id":6202,"materia":"ling","nivel":1,"enunciado":"No esporte, a expressão “fair play” significa:","opcoes":["Jogo limpo, com respeito ao adversário","Jogar só para ganhar","Jogo sem regras","Partida amistosa sem juiz e sem placar oficial"],"explicacao":"Valoriza a ética esportiva."},{"id":6203,"materia":"ling","nivel":3,"enunciado":"Em inglês, a palavra “although” introduz uma ideia de:","opcoes":["Concessão (embora)","Causa (porque)","Finalidade (para)","Tempo (quando)"],"explicacao":"Although = embora, apesar de."},{"id":6204,"materia":"ling","nivel":2,"enunciado":"Em espanhol, “embarazada” significa:","opcoes":["Grávida","Envergonhada","Embaraçada","Atrasada"],"explicacao":"É um falso cognato."},{"id":6205,"materia":"ling","nivel":2,"enunciado":"Mandioca, aipim e macaxeira são nomes da mesma raiz em regiões diferentes. Isso é variação:","opcoes":["Regional (diatópica)","Histórica","De registro formal e informal","Ortográfica"],"explicacao":"Varia conforme o lugar."},{"id":6206,"materia":"mat","nivel":1,"enunciado":"Um carro faz 12 km por litro. Para percorrer 300 km, ele gasta:","opcoes":["25 litros","36 litros","20 litros","30 litros"],"explicacao":"300 ÷ 12 = 25."},{"id":6207,"materia":"mat","nivel":2,"enunciado":"Uma maquete está na escala 1:50. Um prédio de 10 m de altura fica, na maquete, com:","opcoes":["20 cm","50 cm","2 cm","5 cm"],"explicacao":"1.000 cm ÷ 50 = 20 cm."},{"id":6208,"materia":"mat","nivel":2,"enunciado":"Uma praça circular tem raio de 10 m. Usando π = 3,14, sua área é:","opcoes":["314 m²","62,8 m²","31,4 m²","100 m²"],"explicacao":"A = π r²."},{"id":6209,"materia":"mat","nivel":3,"enunciado":"Em notação científica, 0,00003 é:","opcoes":["3 × 10⁻⁵","3 × 10⁵","3 × 10⁻⁴","30 × 10⁻⁶"],"explicacao":"A vírgula anda 5 casas para a direita."},{"id":6210,"materia":"mat","nivel":2,"enunciado":"Sorteando um número de 1 a 20, a probabilidade de sair um múltiplo de 4 é:","opcoes":["1/4","1/5","1/2","4/20 + 1"],"explicacao":"São 5 múltiplos (4, 8, 12, 16, 20) em 20."},{"id":6211,"materia":"mat","nivel":3,"enunciado":"Quantos centímetros quadrados há em 1 metro quadrado?","opcoes":["10.000","100","1.000","1.000.000"],"explicacao":"1 m² = 100 cm × 100 cm."},{"id":6212,"materia":"mat","nivel":4,"enunciado":"Uma pizzaria oferece 8 sabores. Quantas pizzas diferentes de 2 sabores podem ser feitas?","opcoes":["28","56","16","64"],"explicacao":"C(8,2) = 28."},{"id":6213,"materia":"fis","nivel":2,"enunciado":"A 60 km/h, quanto tempo um ônibus leva para percorrer 150 km?","opcoes":["2 h 30 min","2 h","3 h","1 h 30 min"],"explicacao":"150 ÷ 60 = 2,5 h."},{"id":6214,"materia":"fis","nivel":2,"enunciado":"Um carro vai de 0 a 20 m/s em 5 segundos. Sua aceleração média é:","opcoes":["4 m/s²","100 m/s²","25 m/s²","15 m/s²"],"explicacao":"a = 20 ÷ 5."},{"id":6215,"materia":"fis","nivel":1,"enunciado":"O peso de uma pessoa de 60 kg na Terra (g = 10 m/s²) é:","opcoes":["600 N","60 N","6 N","6.000 N"],"explicacao":"P = m × g."},{"id":6216,"materia":"fis","nivel":3,"enunciado":"Na garrafa térmica, as paredes espelhadas servem para reduzir a perda de calor por:","opcoes":["Radiação","Condução","Convecção","Evaporação"],"explicacao":"O vácuo entre as paredes reduz condução e convecção."},{"id":6217,"materia":"fis","nivel":2,"enunciado":"Numa freada brusca, o passageiro é lançado para a frente por causa da:","opcoes":["Inércia","Gravidade","Força magnética","Pressão do ar"],"explicacao":"Por isso o cinto de segurança é essencial."},{"id":6218,"materia":"fis","nivel":3,"enunciado":"Uma faca afiada corta melhor porque:","opcoes":["A força é aplicada numa área menor, aumentando a pressão","A faca fica mais pesada e firme na mão de quem corta","Diminui a pressão","Aumenta a área de contato"],"explicacao":"P = F ÷ A."},{"id":6219,"materia":"qui","nivel":2,"enunciado":"Tomar bicarbonato de sódio para aliviar a azia é um exemplo de reação de:","opcoes":["Neutralização entre ácido e base","Combustão","Oxidação do ferro no estômago","Fusão"],"explicacao":"O bicarbonato neutraliza o excesso de ácido do estômago."},{"id":6220,"materia":"qui","nivel":3,"enunciado":"O gelo seco passa direto do estado sólido para o gasoso. Esse processo é a:","opcoes":["Sublimação","Fusão","Condensação","Solidificação"],"explicacao":"O gelo seco é CO₂ sólido."},{"id":6221,"materia":"qui","nivel":1,"enunciado":"O vinagre contém, principalmente, o ácido:","opcoes":["Acético","Sulfúrico","Clorídrico","Cítrico"],"explicacao":"O cítrico está no limão."},{"id":6222,"materia":"qui","nivel":4,"enunciado":"Quando a queima de um combustível é incompleta, por falta de oxigênio, forma-se um gás muito tóxico, o:","opcoes":["Monóxido de carbono (CO)","Oxigênio (O₂)","Gás nitrogênio (N₂)","Vapor d’água"],"explicacao":"Por isso é perigoso ligar o carro em garagem fechada."},{"id":6223,"materia":"qui","nivel":3,"enunciado":"O biodiesel é produzido, principalmente, a partir de:","opcoes":["Óleos vegetais e gorduras animais","Petróleo bruto e derivados do gás natural","Carvão mineral","Urânio"],"explicacao":"É um combustível renovável."},{"id":6224,"materia":"bio","nivel":2,"enunciado":"O bioma brasileiro mais devastado, que hoje tem pouco de sua área original, é a:","opcoes":["Mata Atlântica","Amazônia","Pantanal","Caatinga"],"explicacao":"Restam cerca de 12% da cobertura original."},{"id":6225,"materia":"bio","nivel":4,"enunciado":"Peixes grandes, como o atum, acumulam mais mercúrio que os pequenos. Isso se deve à:","opcoes":["Bioacumulação (magnificação trófica) ao longo da cadeia alimentar","Fotossíntese","Respiração celular dos peixes maiores","Polinização"],"explicacao":"O metal se acumula a cada nível da cadeia."},{"id":6226,"materia":"bio","nivel":3,"enunciado":"O pão cresce porque as leveduras, na fermentação, liberam:","opcoes":["Gás carbônico","Oxigênio","Nitrogênio","Álcool sólido"],"explicacao":"O CO₂ forma bolhas na massa."},{"id":6227,"materia":"bio","nivel":3,"enunciado":"Um organismo transgênico é aquele que:","opcoes":["Recebeu um gene de outra espécie","Foi criado sem DNA","Vive só em laboratório","Não pode se reproduzir nunca, por ser estéril"],"explicacao":"Ex.: soja resistente a herbicida."},{"id":6228,"materia":"bio","nivel":1,"enunciado":"No sangue, as células que transportam o oxigênio são as:","opcoes":["Hemácias","Plaquetas","Leucócitos","Plasmócitos"],"explicacao":"Contêm hemoglobina."},{"id":6229,"materia":"bio","nivel":3,"enunciado":"Na esquistossomose (barriga-d’água), o hospedeiro intermediário é o:","opcoes":["Caramujo","Barbeiro","Mosquito","Cachorro"],"explicacao":"O verme penetra na pele em águas contaminadas."},{"id":6230,"materia":"his","nivel":2,"enunciado":"O ciclo da borracha, no fim do século XIX, enriqueceu principalmente a região:","opcoes":["Amazônica, como Manaus e Belém","Sul, como Porto Alegre","Sudeste, como São Paulo e Rio de Janeiro","Centro-Oeste, como Cuiabá"],"explicacao":"Manaus construiu o Teatro Amazonas."},{"id":6231,"materia":"his","nivel":4,"enunciado":"A Lei de Terras de 1850 estabeleceu que as terras só poderiam ser obtidas por:","opcoes":["Compra, dificultando o acesso de pobres e ex-escravizados","Doação do imperador a quem as ocupasse","Ocupação livre","Sorteio"],"explicacao":"Concentrou ainda mais a terra."},{"id":6232,"materia":"his","nivel":4,"enunciado":"A Cabanagem, revolta popular do período regencial, ocorreu no:","opcoes":["Pará","Rio Grande do Sul","Bahia","Maranhão"],"explicacao":"1835–1840."},{"id":6233,"materia":"his","nivel":3,"enunciado":"Na democracia de Atenas, na Grécia antiga, NÃO podiam votar:","opcoes":["Mulheres, escravizados e estrangeiros","Homens atenienses adultos e livres","Soldados atenienses","Filósofos atenienses"],"explicacao":"Só uma minoria era considerada cidadã."},{"id":6234,"materia":"geo","nivel":1,"enunciado":"Na rosa dos ventos, a direção oposta ao nordeste é o:","opcoes":["Sudoeste","Sudeste","Noroeste","Sul"],"explicacao":"Direções opostas ficam em lados contrários."},{"id":6235,"materia":"fil","nivel":3,"enunciado":"Em “O Príncipe”, Maquiavel afirma que, se não for possível ser as duas coisas, é melhor para o governante ser:","opcoes":["Temido do que amado","Amado do que temido","Pobre do que rico","Bondoso do que eficiente"],"explicacao":"Separou a política da moral cristã."},{"id":6236,"materia":"fil","nivel":3,"enunciado":"Para John Locke, a mente humana, ao nascer, é como uma:","opcoes":["Tábula rasa (folha em branco)","Caverna escura","Máquina perfeita","Ideia inata"],"explicacao":"O conhecimento vem da experiência (empirismo)."},{"id":6237,"materia":"fil","nivel":4,"enunciado":"Para Pierre Bourdieu, os conhecimentos, gostos e diplomas herdados da família formam o:","opcoes":["Capital cultural","Capital financeiro","Fato social","Imperativo categórico"],"explicacao":"Ajuda a explicar a desigualdade escolar."},{"id":6238,"materia":"fil","nivel":3,"enunciado":"Os estoicos ensinavam que devemos:","opcoes":["Aceitar com serenidade o que não podemos controlar","Buscar o prazer acima de tudo, sem pensar nas consequências","Duvidar de tudo","Desprezar a razão"],"explicacao":"Sêneca, Epiteto e Marco Aurélio."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
